(() => {
'use strict';
const $=s=>document.querySelector(s),c=window.HVT;let mode='login';
function status(text,error=false){$('#accountStatus').hidden=!text;$('#accountStatus').textContent=text;$('#accountStatus').classList.toggle('error',error)}
function render(){const user=c.currentUser();$('#accountBtn').textContent=user?'Tài khoản':'Đăng nhập / Đăng ký';$('#accountForms').hidden=!!user;$('#accountProfile').hidden=!user;if(user){$('#accountEmail').textContent=user.email||'';$('#accountName').textContent=String(user.user_metadata?.display_name||'')}$('#accountSubmit').disabled=!c.configured;if(!c.configured)status('Tài khoản sẽ hoạt động khi website đã kết nối Supabase. Bạn vẫn xem được toàn bộ thư viện.',false)}
function selectMode(next){mode=next;$('#accountNameLabel').hidden=mode!=='register';$('#accountConfirmLabel').hidden=mode!=='register';$('#accountRegistrationHint').hidden=mode!=='register';$('#accountForm').elements.confirm.required=mode==='register';$('#accountForm').elements.password.autocomplete=mode==='register'?'new-password':'current-password';$('#accountSubmit').textContent=mode==='register'?'Đăng ký':'Đăng nhập';document.querySelectorAll('[data-account-mode]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.accountMode===mode)));status('');render()}
$('#accountBtn').onclick=()=>{status('');render();$('#accountDialog').showModal()};$('#accountClose').onclick=$('#continueAsGuest').onclick=()=>$('#accountDialog').close();$('#accountDialog').addEventListener('close',()=>{$('#accountForm').reset()});document.querySelectorAll('[data-account-mode]').forEach(b=>b.onclick=()=>selectMode(b.dataset.accountMode));
$('#accountForm').onsubmit=async e=>{e.preventDefault();const form=e.target,f=new FormData(form),email=f.get('email').trim(),password=f.get('password');if(mode==='register'&&password!==f.get('confirm')){status('Hai mật khẩu chưa trùng nhau.',true);return}$('#accountSubmit').disabled=true;status(mode==='register'?'Đang đăng ký…':'Đang đăng nhập…');try{if(mode==='register'){const result=await c.register(email,password,f.get('name').trim());form.reset();render();status(result?.access_token?'Đăng ký thành công. Bạn đã đăng nhập.':'Đã tiếp nhận đăng ký. Nếu cần xác nhận email, hãy kiểm tra hộp thư và Spam, xác nhận rồi quay lại đăng nhập.')}else{await c.memberSignIn(email,password);form.reset();render();status('Đăng nhập thành công. Toàn bộ nội dung vẫn luôn mở cho mọi người.')}}catch(error){form.elements.password.value='';form.elements.confirm.value='';const msg=error.message;status(/signup.*disabled|signups.*not allowed/i.test(msg)?'Chức năng đăng ký chưa được bật trong Supabase. Bạn vẫn xem được toàn bộ nội dung.':msg,true)}finally{$('#accountSubmit').disabled=!c.configured}};
$('#accountLogout').onclick=async()=>{try{await c.signOut();status('Đã đăng xuất. Bạn tiếp tục xem toàn bộ thư viện bình thường.')}catch{status('Đã đăng xuất trên trang này.')}render()};window.addEventListener('hvt-auth-change',render);window.addEventListener('hvt-auth-lost',()=>{render();status('Phiên đã hết hạn. Bạn vẫn có thể tiếp tục đọc mà không đăng nhập.')});render();c.consumeAuthRedirect().then(user=>{if(user){render();status('Email đã xác nhận. Bạn đã đăng nhập.');$('#accountDialog').showModal()}}).catch(error=>{status(error.message,true);$('#accountDialog').showModal()});
})();
